"""BPC 2026 guidance agent (single file): RL3 = attention policy over all balloons that picks the target, the
approach speed level and the launch time; GNC (navigation, ZEM guidance, attitude control) flies it.

Uses only observations and given_parameters. Policy weights are embedded below (trained offline with PPO,
see the team's training code). Generated by dev/make_single_file.py from rl3_policy_40915200.npz.
"""
import base64
import io
from pathlib import Path

import numpy as np

_WEIGHTS_B64 = ""
_SL_B64 = ""  # empty = no learned reach model


def _embedded_weights():
    return {k: v for k, v in np.load(io.BytesIO(base64.b64decode(_WEIGHTS_B64))).items()}


# ============================================================================ learned reach model (rl2_sl.py)

IN_TOK = [0, 1, 2, 3, 4, 5, 6, 7, 8, 11, 12, 13]  # token columns used (skips t_hat, p_hat, alive)


def load_sl(path):
    d = dict(np.load(path))
    n = int(d["n_layers"])
    layers = [(d[f"W{i}"], d[f"b{i}"]) for i in range(n)]
    mu, sd, ns = d["mu"], d["sd"], int(d["n_str"])

    def sl(tok, g):
        z = (np.concatenate([np.broadcast_to(g, (len(tok), 6)), tok[:, IN_TOK]], 1) - mu) / sd
        for W, b in layers[:-1]:
            z = np.maximum(z @ W + b, 0)
        W, b = layers[-1]
        o = z @ W + b
        p = 1 / (1 + np.exp(-o[:, :ns]))
        t = np.maximum(o[:, ns:], 0.0)
        best = np.argmax(p - 0.02 * t, 1)  # best level: likely hit, prefer faster
        r = np.arange(len(tok))
        return t[r, best] / 10.0, p[r, best]

    return sl

# ============================================================================ GNC base (gnc_agent.py)

import numpy as np

from BalloonPoppingGymEnv.agents.base_agent import BaseAgent
from BalloonPoppingGymEnv.envs.balloon_world import get_initial_attitude

G = np.array([0.0, 0.0, -9.81])


def quat_to_R(q):
    """Body -> launch frame rotation, q = (e0, e1, e2, e3) scalar first."""
    e0, e1, e2, e3 = q
    return np.array(
        [
            [1 - 2 * (e2 * e2 + e3 * e3), 2 * (e1 * e2 - e0 * e3), 2 * (e1 * e3 + e0 * e2)],
            [2 * (e1 * e2 + e0 * e3), 1 - 2 * (e1 * e1 + e3 * e3), 2 * (e2 * e3 - e0 * e1)],
            [2 * (e1 * e3 - e0 * e2), 2 * (e2 * e3 + e0 * e1), 1 - 2 * (e1 * e1 + e2 * e2)],
        ]
    )


def quat_step(q, w, dt):
    """q <- q ⊗ exp(w dt / 2), w in body frame."""
    v = w * dt
    a = np.linalg.norm(v)
    if a < 1e-12:
        return q
    dw, (dx, dy, dz) = np.cos(a / 2), np.sin(a / 2) * v / a
    e0, e1, e2, e3 = q
    q = np.array(
        [
            e0 * dw - e1 * dx - e2 * dy - e3 * dz,
            e0 * dx + e1 * dw + e2 * dz - e3 * dy,
            e0 * dy - e1 * dz + e2 * dw + e3 * dx,
            e0 * dz + e1 * dy - e2 * dx + e3 * dw,
        ]
    )
    return q / np.linalg.norm(q)


def unit(v):
    n = np.linalg.norm(v)
    return v / n if n > 1e-9 else v * 0.0


class GNCAgent(BaseAgent):
    def __init__(self, given_parameters, **kw):
        super().__init__(given_parameters)
        p = self.given_parameters
        rk, ctrl = p["rocket"], p["rocket"]["control"]
        self.dt = p["simulation"]["time_step"]
        self.elev = p["environment"]["elevation"]
        self.burn_time = rk["motor"]["burn_time"]
        self.max_gimbal = ctrl["max_gimbal_angle"]
        self.max_roll = ctrl["max_roll_torque"]
        self.thr_lo, self.thr_hi = ctrl["throttle_range"]
        self.thr_rate = ctrl["throttle_rate_limit"]

        # tunables (all overridable from cfg.yaml agent_kwargs)
        self.launch_time = kw.get("launch_time", 20.0)
        self.incl_head = np.array([kw.get("inclination", 90.0), kw.get("heading", 0.0)])
        self.margin = kw.get("margin", 0.5)  # (m/s^2) thrust held back when planning
        self.stretch = kw.get("stretch", 1.3)  # fly t_go = stretch * min time (less speed build-up)
        self.switch_margin = kw.get("switch_margin", 0.3)  # (s) hysteresis
        self.switch_ratio = kw.get("switch_ratio", 1.15)  # keep target unless another is this much faster
        self.excess_dir = kw.get("excess_dir", 0)  # see _spend_excess
        self.excess_frac = kw.get("excess_frac", 1.0)
        self.nav_N = kw.get("nav_N", 2.0)  # ZEM guidance gain
        self.t_go_min = kw.get("t_go_min", 0.3)  # (s) guidance singularity guard
        self.t_grid = np.arange(0.1, kw.get("horizon", 15.0), 0.1)
        self.n_cand = int(kw.get("n_cand", 8))  # candidates expanded by the lookahead
        self.gamma = kw.get("gamma", 0.5)  # weight of the second leg
        self.min_alt = kw.get("min_alt", 30.0)  # (m AGL) ground avoidance floor
        self.k_att = kw.get("k_att", 2.0)  # (rad/s per rad) attitude -> rate
        self.max_rate = kw.get("max_rate", 1.5)  # (rad/s)
        self.k_rate = kw.get("k_rate", 10.0)  # (deg per rad/s) rate -> gimbal
        self.k_pos = kw.get("k_pos", 0.02)  # GNSS position blend per step
        self.k_vel = kw.get("k_vel", 0.05)  # GNSS velocity blend per step
        self.k_roll = kw.get("k_roll", 20.0)  # (N m per rad/s)
        self.coast = kw.get("coast", 0)  # 1: plan hits past burnout (thrust only for the burn left, then ballistic)
        # coast >= 2: burn-tail coast planner (see _coast_plan)
        self.plan_T = kw.get("plan_T", 4.0)  # (s) burn left when the planner may take over
        self.align_T = kw.get("align_T", 1.0)  # (s) last burn seconds flown along the velocity: no angle of attack
        self.plan_min = kw.get("plan_min", 0.3)  # expected coast hits needed to take over from the target
        self.plan_every = int(kw.get("plan_every", 20))  # (steps) replanning period
        # eob=1: end-of-burn mode (see _eob): in the last eob_T s of the burn, a target that cannot be hit before burnout
        # (t_go * stretch > burn left) is aimed at a hit <= eob_tau s after it; the thrust is held for the last eob_hold s.
        # eob=2: "cannot be hit before burnout" = no constant force within the thrust hits it by burnout; once on, the
        # mode stays on for that target
        self.eob = int(kw.get("eob", 0))
        self.eob_T = kw.get("eob_T", 2.0)  # (s) burn left when the mode may engage
        self.eob_tau = kw.get("eob_tau", 2.0)  # (s) latest hit time after burnout
        self.eob_hold = kw.get("eob_hold", 0.25)  # (s) last burn seconds with the thrust held
        self.eob_f = None  # the mode's last force (held at the end), None when off
        # actuator lag (scenario 3 / 4): each actuator is y = a u + (1 - a) y_prev with a = 1 / (1 + tau / dt), then
        # its rate limit and range; tau and the limits are given parameters. lag_comp=1 tracks y and commands the u
        # (inside the action range) whose output is the wanted value -> the lag is cancelled wherever the range allows
        self.lag_comp = int(kw.get("lag_comp", 0))
        alpha = lambda tau: 1.0 / (1.0 + tau / self.dt) if tau else 1.0  # noqa: E731
        self.act_a = np.array([alpha(ctrl.get("gimbal_time_constant"))] * 2
                              + [alpha(ctrl.get("roll_torque_time_constant")), alpha(ctrl.get("throttle_time_constant"))])
        rate = [ctrl.get("gimbal_rate_limit")] * 2 + [ctrl.get("torque_rate_limit"), self.thr_rate]
        self.act_rate = np.array([np.inf if r is None else r * self.dt for r in rate])
        self.act_lo = np.array([-self.max_gimbal, -self.max_gimbal, -self.max_roll, self.thr_lo])
        self.act_hi = np.array([self.max_gimbal, self.max_gimbal, self.max_roll, self.thr_hi])
        self.act_out = np.array([0.0, 0.0, 0.0, 1.0])  # modelled outputs: tvc x, tvc y, roll torque, throttle
        # bwind=1: balloons drift with the air, so their horizontal velocities give the wind at their altitudes; a
        # balloon's predicted path follows that profile as it rises (scenario 4 gust changes every 20 m of altitude)
        self.bwind = int(kw.get("bwind", 0))
        self.bw_h = kw.get("bw_h", 5.0)  # (m) altitude kernel width of the balloon-wind profile
        self.wz = self.elev + np.arange(0.0, 600.0, 2.0)  # (m ASL) profile grid
        self.wprof = None  # (altitude grid (Z,), wind (Z, 2), its altitude integral (Z, 2))
        # bwind >= 4: the profile from ALL past balloon samples instead of the current snapshot (here the wind depends on
        # altitude only and the balloons are its tracers): local-linear running moments on a 0.5 m grid, every 0.1 s;
        # held constant above the highest balloon seen (no assumption about the gust structure there)
        self.hz = self.elev + np.arange(0.0, 1200.0, 0.5)
        self.hmom, self.hrel, self.hstep = np.zeros((5, len(self.hz), 2)), None, 0
        # DP planner (rl2_agent dp > 0 / dp_shadow): its balloon table uses the history profile hprof, collected here
        # even when bwind < 4 (bwind >= 4 shares it as wprof); aim_prof: the profile a planner leg is aimed with
        self.dp_hist = int(kw.get("dp", 0)) > 0 or int(kw.get("dp_shadow", 0)) > 0
        self.hprof = self.aim_prof = None

        # initial thrust acceleration guess from given parameters, refined in flight
        grain = rk["motor"]
        m_grain = (
            np.pi
            * (grain["grain_outer_radius"] ** 2 - grain["grain_initial_inner_radius"] ** 2)
            * grain["grain_initial_height"]
            * grain["grain_density"]
            * grain["grain_number"]
        )
        m0 = (
            rk["rocket_body"]["mass"]
            + grain["dry_mass"]
            + rk["tank"]["initial_liquid_mass"]
            + rk["tank"]["initial_gas_mass"]
            + m_grain
        )
        self.a_thrust = grain["thrust_source"] / m0
        tank, body = rk["tank"], rk["rocket_body"]
        m_end = body["mass"] + grain["dry_mass"] + tank["initial_gas_mass"] + max(
            tank["initial_liquid_mass"] - tank["liquid_mass_flow_rate_out"] * self.burn_time, 0.0)
        self.k_drag = 0.5 * body["power_off_drag"] * np.pi * body["radius"] ** 2 / m_end  # drag accel = k rho |v|^2
        el = np.radians([-30.0, 0.0, 30.0, 60.0])[:, None]; az = np.radians(np.arange(0, 360, 45))[None]
        dirs = np.stack([np.cos(el) * np.cos(az), np.cos(el) * np.sin(az), np.sin(el) + 0 * az], -1).reshape(-1, 3)
        self.plan_dirs = np.vstack([dirs, [0.0, 0.0, 1.0]])  # candidate thrust directions (world)
        self.plan, self.plan_on = None, False

        self.q = np.array(get_initial_attitude(*self.incl_head))
        self.launched_at = None
        self.p_hat = self.v_hat = None
        self.throttle = 1.0  # our model of the actual (rate limited) throttle
        self.target = None
        self.debug = {}

    # ------------------------------------------------------------------ helpers
    def _navigate(self, acc, p_gnss, v_gnss):
        """Complementary filter: INS propagation (accelerometer + attitude), GNSS correction."""
        if self.p_hat is None:
            self.p_hat, self.v_hat = p_gnss.copy(), v_gnss.copy()
            return self.p_hat, self.v_hat
        a = quat_to_R(self.q) @ acc + G
        self.p_hat = self.p_hat + self.v_hat * self.dt + 0.5 * a * self.dt**2
        self.v_hat = self.v_hat + a * self.dt
        self.p_hat += self.k_pos * (p_gnss - self.p_hat)
        self.v_hat += self.k_vel * (v_gnss - self.v_hat)
        return self.p_hat, self.v_hat

    def _burning(self, t):
        return self.launched_at is not None and t < self.launched_at + self.burn_time - self.dt

    def _wind_profile(self, obs):
        """Horizontal wind vs altitude from the airborne balloons: Gaussian kernel (bw_h) over altitude, held constant
        beyond the balloons -> (W, integral of W dz) on self.wz, or None."""
        st, bs = obs["balloon_status"][:, 0], obs["balloon_states"]
        fly = (st == 1) & (bs[:, 2] > self.elev + 1.0)
        if fly.sum() < 3:
            return None
        z, w = bs[fly, 2], bs[fly, 3:5]
        K = np.exp(-0.5 * ((self.wz[:, None] - z[None]) / self.bw_h) ** 2)
        ks = K.sum(1)
        ok = ks > 0.05
        W = (K[ok] @ w) / ks[ok, None]
        W = np.stack([np.interp(self.wz, self.wz[ok], W[:, k]) for k in (0, 1)], 1)
        Wc = np.vstack([np.zeros((1, 2)), np.cumsum(0.5 * (W[1:] + W[:-1]) * np.diff(self.wz)[:, None], 0)])
        return self.wz, W, Wc

    def _hist_add(self, obs):
        """bwind >= 4: add this observation's settled balloons (released >= 0.3 s ago) to the running moments, rebuild."""
        st, bs, t = obs["balloon_status"][:, 0], obs["balloon_states"], float(obs["simulation_time"])
        if self.hrel is None:
            self.hrel = np.full(len(st), np.nan)
        self.hrel[np.isnan(self.hrel) & (st == 1)] = t
        ok = (st == 1) & (t - self.hrel >= 0.3) & (bs[:, 2] > self.elev + 1.0) & np.isfinite(bs[:, 2:5]).all(1)  # one NaN would poison the sums
        if not ok.any():
            return
        z, v = bs[ok, 2].astype(float), bs[ok, 3:5].astype(float)
        dz = self.hz[1] - self.hz[0]
        i = np.clip((z - self.hz[0]) / dz, 0, len(self.hz) - 1.001).astype(int)
        for j in (i, i + 1):  # hat weights to the two neighbouring nodes; moments about each node (local line fit)
            d = z - self.hz[j]; w = 1.0 - np.abs(d) / dz
            for c, q in enumerate((w, w * d, w * d * d)):
                self.hmom[c] += np.bincount(j, q, len(self.hz))[:, None]
            for c, q in ((3, w), (4, w * d)):
                self.hmom[c] += np.stack([np.bincount(j, q * v[:, k], len(self.hz)) for k in (0, 1)], 1)
        s0, s1, s2, t0, t1 = self.hmom
        have = s0[:, 0] > 1e-6
        if have.sum() < 2:
            return
        det = s0 * s2 - s1 * s1
        lin = (det > 1e-4 * s0 * s0 * dz ** 2)[:, 0]  # enough altitude spread in the bin for a local line
        slope = (s0 * t1 - s1 * t0) / np.where(det > 0, det, 1.0)
        near = np.maximum.accumulate(np.where(lin, np.arange(len(lin)), 0))  # else the slope of the nearest line below
        val = (t0 - slope[near] * s1) / np.maximum(s0, 1e-12)
        W = np.stack([np.interp(self.hz, self.hz[have], val[have, k]) for k in (0, 1)], 1)  # constant beyond the data
        Wc = np.vstack([np.zeros((1, 2)), np.cumsum(0.5 * (W[1:] + W[:-1]) * dz, 0)])
        self.hprof = (self.hz, W, Wc)
        if self.bwind >= 4:
            self.wprof = self.hprof

    def _bdrift(self, z0, vz, t, wp=None):
        """Extra displacement of balloons at z0 rising at vz over t beyond constant velocity (broadcast) -> (..., 3).
        wp: wind profile to use (default wprof)."""
        wp = self.wprof if wp is None else wp
        if wp is None:
            return np.zeros(np.broadcast(z0, vz, t).shape + (3,))
        wz, W, Wc = wp
        z0, vz, t = np.broadcast_arrays(z0, vz, t)
        z1 = z0 + vz * t
        rising = np.abs(vz) > 0.2
        out = np.zeros(z0.shape + (3,))
        for k in (0, 1):
            dW = np.interp(z1, wz, Wc[:, k]) - np.interp(z0, wz, Wc[:, k])
            out[..., k] = np.where(rising, dW / np.where(rising, vz, 1.0) - np.interp(z0, wz, W[:, k]) * t, 0.0)
        return out

    def _btable(self, obs, H=15.0, dt=0.1, min_alt=3.0):
        """DP planner's balloon table: the airborne balloons (alive, > min_alt AGL) at t = 0, dt, ..., H, drifting on the
        history profile -> (their indices, positions (K + 1, M, 3))."""
        st, bs = obs["balloon_status"][:, 0], obs["balloon_states"]
        alive = np.flatnonzero((st == 1) & (bs[:, 2] > self.elev + min_alt) & np.isfinite(bs).all(1))
        t = np.arange(int(round(H / dt)) + 1) * dt
        bp, bv = bs[alive, :3].astype(float), bs[alive, 3:].astype(float)
        return alive, bp[None] + bv[None] * t[:, None, None] + self._bdrift(bp[None, :, 2], bv[None, :, 2], t[:, None], self.hprof)

    def _reach_time(self, p, v, bpos, bvel):
        """Min time to hit each balloon with constant specific force |f| <= a_thrust - margin.

        Hit at t  <=>  |r + (vb - v) t - G t^2 / 2| <= a t^2 / 2   (drag ignored).
        Broadcasts: p, v (..., 3); bpos, bvel (..., N, 3) -> (..., N). inf if unreachable.
        """
        tg = self.t_grid[:, None]
        r = (bpos - p[..., None, :])[..., None, :]
        vr = (bvel - v[..., None, :])[..., None, :]
        miss = r + vr * tg - 0.5 * G * tg**2
        if self.bwind:
            miss = miss + self._bdrift(bpos[..., None, 2], bvel[..., None, 2], self.t_grid)
        ok = np.linalg.norm(miss, axis=-1) <= (self.a_thrust - self.margin) * self._burn_disp(self.t_grid)
        return np.where(ok.any(axis=-1), self.t_grid[np.argmax(ok, axis=-1)], np.inf)

    def _select_target(self, p, v, obs):
        """Two-step lookahead: cost = t(target) + gamma * min t(target -> next)."""
        status = obs["balloon_status"][:, 0]
        states = obs["balloon_states"]
        alive = np.flatnonzero(status == 1)
        if alive.size == 0:
            return None, None
        bp, bv = states[alive, :3], states[alive, 3:]
        t1 = self._reach_time(p, v, bp, bv)
        cand = np.argsort(t1)[: self.n_cand]
        cand = cand[np.isfinite(t1[cand])]
        if self.target is not None and status[self.target] == 1:
            cur = np.flatnonzero(alive == self.target)[0]
            if np.isfinite(t1[cur]) and cur not in cand:
                cand = np.append(cand, cur)
        if cand.size == 0:
            return None, None
        tc = t1[cand][:, None]
        arr_p = bp[cand] + bv[cand] * tc
        arr_v = v + 2 * (bp[cand] - p + (bv[cand] - v) * tc) / tc  # v + a t
        t2 = self._reach_time(arr_p, arr_v, bp[None] + bv[None] * tc[:, :, None], bv[None])
        t2[np.arange(cand.size), cand] = np.inf  # not itself
        t2 = np.minimum(t2.min(axis=1), self.t_grid[-1])
        cost = t1[cand] + self.gamma * t2
        i = np.argmin(cost)
        if self.target is not None and status[self.target] == 1:
            j = np.flatnonzero(alive[cand] == self.target)
            if j.size and cost[j[0]] <= self.switch_ratio * cost[i] + self.switch_margin:
                return self.target, t1[cand[j[0]]]
        return alive[cand[i]], t1[cand[i]]

    def _burn_disp(self, t):
        """Displacement per unit specific force held for t (t^2/2), or only for the burn left, then coasting."""
        if not self.coast:
            return 0.5 * t**2
        tb = self.burn_left
        return np.where(t <= tb, 0.5 * t**2, tb * (t - 0.5 * tb))

    def _wind(self, obs):
        """Wind estimate: horizontal drift of the airborne balloons (they move with the air)."""
        st, bs = obs["balloon_status"][:, 0], obs["balloon_states"]
        fly = (st == 1) & (bs[:, 2] > self.elev + 2.0)
        return np.r_[np.median(bs[fly, 3:5], 0), 0.0] if fly.any() else np.zeros(3)

    def _fly(self, p, v, f, t_burn, w, T, dt=0.1, f0=None):
        """Point-mass paths of K candidates: specific force f (K, 3) until t_burn (its last align_T seconds along the
        velocity), then coasting; gravity + drag against wind w. The thrust starts at f0 (current attitude x throttle)
        and turns / ramps at the attitude-rate and throttle-rate limits. -> positions (n + 1, K, 3) at t = 0, dt, ..."""
        n = int(round(T / dt)); P = np.empty((n + 1,) + p.shape); P[0] = p
        fm = np.linalg.norm(f, axis=-1)
        cd = np.broadcast_to(unit(f0) if f0 is not None else np.array([0.0, 0.0, 1.0]), p.shape).copy()  # thrust direction
        cm = np.full(len(p), np.linalg.norm(f0) if f0 is not None else self.a_thrust)  # thrust magnitude
        w_max, m_rate = 0.8 * self.max_rate * dt, self.thr_rate * self.a_thrust * dt
        for i in range(n):
            ti = i * dt
            vr = v - w
            rho = 1.225 * np.clip(1.0 - 2.2558e-5 * p[..., 2:3], 0.5, 1.0) ** 4.2559
            a = G - self.k_drag * rho * np.linalg.norm(vr, axis=-1, keepdims=True) * vr
            if ti < t_burn:
                td = v / np.maximum(np.linalg.norm(v, axis=-1, keepdims=True), 1e-6) if ti >= t_burn - self.align_T \
                    else f / np.maximum(fm[:, None], 1e-9)
                th = np.arccos(np.clip((cd * td).sum(-1), -1.0, 1.0))
                al = np.minimum(th, w_max); sn = np.maximum(np.sin(th), 1e-9)
                cd = np.where((th > 1e-6)[:, None], (np.sin(th - al)[:, None] * cd + np.sin(al)[:, None] * td) / sn[:, None], cd)
                cm = cm + np.clip(fm - cm, -m_rate, m_rate)
                a = a + cm[:, None] * cd
            v = v + a * dt; p = p + v * dt; P[i + 1] = p
        return P

    def _coast_plan(self, p, v, obs, t_left, horizon=12.0, dt=0.1):
        """Burn-tail coast planner: for each candidate thrust (direction x magnitude) held for the burn left, predict
        the path (incl. coasting) and every live balloon's closest approach; P(hit) falls off with the miss distance
        beyond 1.2 m, with an error that grows with time (worse after burnout). -> (best force, expected hits,
        expected hits of every candidate)."""
        st, bs = obs["balloon_status"][:, 0], obs["balloon_states"]
        alive = np.flatnonzero(st == 1)
        if alive.size == 0:
            return None, 0.0, None
        mags = self.a_thrust * np.array([self.thr_lo, 0.5 * (self.thr_lo + self.thr_hi), self.thr_hi])
        F = np.vstack([(self.plan_dirs[None] * mags[:, None, None]).reshape(-1, 3), -G])  # + "hold altitude"
        K, w = len(F), self._wind(obs)
        f0 = quat_to_R(self.q)[:, 2] * self.throttle * self.a_thrust  # thrust now
        P = self._fly(np.tile(p, (K, 1)), np.tile(v, (K, 1)), F, t_left, w, t_left + horizon, dt, f0)
        b0, bv = bs[alive, :3], bs[alive, 3:]
        best = np.full((K, alive.size), np.inf); tbest = np.zeros((K, alive.size))
        live = np.ones(K, bool)
        for i in range(len(P) - 1):  # exact closest approach on each segment (relative motion ~ linear within dt)
            live &= P[i, :, 2] > self.elev
            r0 = (b0 + bv * i * dt)[None] - P[i][:, None]; r1 = (b0 + bv * (i + 1) * dt)[None] - P[i + 1][:, None]
            dr = r1 - r0
            s = np.clip(-(r0 * dr).sum(-1) / np.maximum((dr * dr).sum(-1), 1e-9), 0.0, 1.0)
            dist = np.linalg.norm(r0 + dr * s[..., None], axis=-1)
            dist[~live] = np.inf
            upd = dist < best
            best[upd] = dist[upd]; tbest[upd] = ((i + s) * dt)[upd]
        sig = 0.3 + 0.05 * tbest + 0.4 * np.maximum(tbest - t_left, 0.0)
        eh = np.exp(-0.5 * (np.maximum(best - 1.2, 0.0) / sig) ** 2).sum(1)
        k = int(np.argmax(eh))
        return F[k], float(eh[k]), eh

    def _guidance(self, p, v, bpos, bvel, t_go):
        """N * zero-effort-miss / t_go^2, gravity cancelled separately (N = 2: constant-thrust hit).
        coast: a hit after burnout needs force f = (miss incl. gravity) / _burn_disp(t_go) while burning."""
        t_go = max(t_go * self.stretch, self.t_go_min)
        if self.bwind or self.aim_prof is not None:
            bpos = bpos + self._bdrift(bpos[2], bvel[2], t_go, self.aim_prof)
        if self.coast and t_go > self.burn_left:
            return 0.5 * self.nav_N * (bpos - p + (bvel - v) * t_go - 0.5 * G * t_go**2) / self._burn_disp(t_go) + G
        return self.nav_N * (bpos - p + (bvel - v) * t_go) / t_go**2

    def _eob(self, p, v, obs, t_go, f):
        """End-of-burn mode: the policy's target cannot be hit before burnout (eob=1: t_go * stretch > burn left T;
        eob=2: see _eob_pre), so hit it tau in (0, eob_tau] s after burnout with a constant force over the rest of the burn:
        B(T + tau) = p + v (T + tau) + G (T + tau)^2 / 2 + f_net (T^2 / 2 + T tau), f = f_net - G; tau minimises |f|
        (capped at the thrust; no floor on f_z). The last eob_hold s hold the thrust. -> force (f if the mode is off)."""
        T = self.burn_left
        if self.eob_f is not None and T <= self.eob_hold:
            return self.eob_f
        b = obs["balloon_states"][self.target] if self.target is not None else None
        if b is None or T > self.eob_T or (p[2] - self.elev < self.min_alt and v[2] < 0) or \
                (self.eob == 1 and t_go * self.stretch <= T) or (self.eob >= 2 and self._eob_pre(p, v, b, T)):
            self.eob_f = None
            return f
        tau = np.arange(0.05, self.eob_tau + 1e-9, 0.05)
        tt = T + tau
        B = b[:3] + b[3:] * tt[:, None]
        if self.bwind:
            B = B + self._bdrift(b[2], b[5], tt, self.aim_prof)
        F = (B - p - v * tt[:, None] - 0.5 * G * tau[:, None] ** 2) / (0.5 * T**2 + T * tau)[:, None] - G
        k = int(np.argmin(np.linalg.norm(F, axis=1)))
        fe = F[k] * min(1.0, self.a_thrust * self.thr_hi / max(np.linalg.norm(F[k]), 1e-9))
        self.eob_f, self.eob_tgt = fe, self.target
        self.debug_eob = (T, tau[k], np.linalg.norm(F[k]))
        return fe

    def _eob_pre(self, p, v, b, T):
        """eob=2: True when the target b can be hit by burnout with a constant force within the thrust (then the
        normal guidance flies it), unless the mode is already on for this target."""
        if self.eob_f is not None and self.eob_tgt == self.target:
            return False
        t = np.append(np.arange(0.05, T, 0.05), T)
        B = b[:3] + b[3:] * t[:, None]
        if self.bwind:
            B = B + self._bdrift(b[2], b[5], t, self.aim_prof)
        F = 2.0 * (B - p - v * t[:, None]) / (t**2)[:, None] - G
        return bool((np.linalg.norm(F, axis=1) <= self.a_thrust * self.thr_hi).any())

    def _saturate(self, a_cmd):
        """Specific force for a_cmd, scaled so gravity compensation always fits in a_thrust."""
        g = -G
        a = a_cmd.copy()
        a[2] = max(a[2], 1.0 - g[2])  # never thrust downward
        # largest s in [0, 1] with |s a + g| <= a_thrust
        A, B, C = a @ a, 2 * a @ g, g @ g - self.a_thrust**2
        s = 1.0
        if A > 1e-9 and (a + g) @ (a + g) > self.a_thrust**2:
            s = max((-B + np.sqrt(max(B * B - 4 * A * C, 0.0))) / (2 * A), 0.0)
        return s * a + g

    def _spend_excess(self, f, v):
        """Throttling down does not save propellant, so put unused thrust along `excess_dir`
        (0: throttle down, 1: straight up = store altitude, 2: along velocity = speed up)."""
        mode = int(self.excess_dir)
        if mode == 0:
            return f
        d = np.array([0.0, 0.0, 1.0]) if mode == 1 else unit(v)
        if not d.any():
            return f
        # largest k >= 0 with |f + k d| = a_thrust
        b, c = f @ d, f @ f - self.a_thrust**2
        k = -b + np.sqrt(max(b * b - c, 0.0))
        return f + max(k, 0.0) * self.excess_frac * d

    def _attitude_control(self, f_des, gyro):
        """TVC and roll command to point the nose (body z) along f_des."""
        R = quat_to_R(self.q)
        d_body = R.T @ unit(f_des)
        err = np.cross([0.0, 0.0, 1.0], d_body)  # rotation axis * sin(angle)
        ang = np.arctan2(np.linalg.norm(err), d_body[2])
        w_cmd = self.k_att * ang * unit(err)
        w_cmd = w_cmd * min(1.0, self.max_rate / max(np.linalg.norm(w_cmd), 1e-9))
        tvc = self.k_rate * (w_cmd[:2] - gyro[:2])
        tvc *= min(1.0, self.max_gimbal / max(np.linalg.norm(tvc), 1e-9))
        roll = np.clip(-self.k_roll * gyro[2], -self.max_roll, self.max_roll)
        return tvc, roll

    # ------------------------------------------------------------------ main
    def get_action(self, obs):
        if self.bwind >= 4 or self.dp_hist:  # the history profile collects from the first step (also on the pad)
            self.hstep += 1
            if self.hstep % 10 == 1:
                self._hist_add(obs)
        action = self._gnc_action(obs)
        if self.lag_comp and self.launched_at is not None:  # flying: the environment applies this step's commands
            want = np.array([*action["tvc"], action["roll"], action["throttle"]], float)
            y, a = self.act_out, self.act_a
            u = np.clip(y + (np.clip(want, y - self.act_rate, y + self.act_rate) - y) / a, self.act_lo, self.act_hi)
            self.act_out = np.clip(np.clip(a * u + (1 - a) * y, y - self.act_rate, y + self.act_rate), self.act_lo, self.act_hi)
            action.update(tvc=u[:2], roll=float(u[2]), throttle=float(u[3]))
        return action

    def _gnc_action(self, obs):
        t = float(obs["simulation_time"])
        sens = obs["rocket_sensors"]
        action = {
            "launch": t >= self.launch_time,
            "launch_inclination_heading": self.incl_head,
            "tvc": np.zeros(2),
            "roll": 0.0,
            "throttle": 1.0,
        }
        if np.isnan(sens).any():
            return action
        if self.launched_at is None:
            self.launched_at = t - self.dt

        gyro, acc = sens[:3], sens[3:6]
        self.q = quat_step(self.q, gyro, self.dt)
        p, v = self._navigate(acc, sens[6:9], sens[9:12])

        if not self._burning(t):
            self.debug = {"t": t, "target": None, "q": self.q.copy()}
            return action

        # refine thrust acceleration estimate (axial specific force / throttle)
        thr = self.act_out[3] if self.lag_comp else self.throttle  # lag_comp: the throttle actually applied
        if thr > 0.3 and acc[2] > 1.0:
            self.a_thrust += 0.05 * (acc[2] / thr - self.a_thrust)

        self.burn_left = max(self.launched_at + self.burn_time - t, self.dt)
        self.step_i = getattr(self, "step_i", 0) + 1
        if 0 < self.bwind < 4 and self.step_i % 5 == 1:
            self.wprof = self._wind_profile(obs)
        self.target, t_go = self._select_target(p, v, obs)
        if self.target is None:
            a_cmd = np.zeros(3)
        else:
            b = obs["balloon_states"][self.target]
            a_cmd = self._guidance(p, v, b[:3], b[3:], t_go)

        # ground avoidance: never plan to fall below min_alt
        alt = p[2] - self.elev
        if alt < self.min_alt and v[2] < 0:
            a_cmd[2] = max(a_cmd[2], v[2] ** 2 / (2 * max(alt, 1.0)))

        f = self._saturate(a_cmd)
        f = self._spend_excess(f, v)
        if self.eob:
            f = self._eob(p, v, obs, t_go, f)
        if self.coast >= 2 and self.burn_left <= self.plan_T:
            # the target cannot be hit before burnout (or there is none): the planner may take over for the rest
            if not self.plan_on and (self.target is None or t_go * self.stretch > self.burn_left):
                if self.plan is None or self.step_i - self.plan[2] >= self.plan_every:
                    fp, eh, _ = self._coast_plan(p, v, obs, self.burn_left)
                    self.plan = (fp, eh, self.step_i)
                    self.plan_on = fp is not None and eh >= self.plan_min
            if self.plan_on:
                f = self.plan[0].copy()
                if self.burn_left <= self.align_T:  # along the velocity: no angle of attack at burnout
                    f = np.linalg.norm(f) * unit(v)
        thr_cmd = float(np.clip(np.linalg.norm(f) / self.a_thrust, self.thr_lo, self.thr_hi))
        step = self.thr_rate * self.dt
        self.throttle = float(np.clip(thr_cmd, self.throttle - step, self.throttle + step))

        tvc, roll = self._attitude_control(f, gyro)
        action.update(tvc=tvc, roll=float(roll), throttle=self.throttle)
        self.debug = {"t": t, "target": self.target, "q": self.q.copy(), "f": f}
        return action

# ============================================================================ DP planner (dp_plan.py)

DP_G = np.array([0.0, 0.0, -9.81])
DP_CFG = dict(D=4, W=24, B0=16, Bk=6, S0=(1.05, 1.25, 1.5), S1=(1.05, 1.3), lam=0.35, dmiss=2.0, mc=40, T=60,
              td=0.0, pc=(0.75, 0.90, 0.93, 20.0), dk=2, dv=3.0, per_m=2, post=1.0, alt=3.0, fz=1.0, hit=1.0,
              drag=None)


def dp_w(t, tb):
    """Displacement per unit specific force: held for t (t^2/2), or only for the burn left tb, then coasting."""
    return np.where(t <= tb, 0.5 * t * t, tb * (t - 0.5 * tb))


def dp_reach(B, dt, P, V, K0, tb, U, a, trate, td, T, mc, fz=1.0, hit=1.0, Ad=None):
    """First feasible leg time (table steps on 1..T, coarser for long legs) from nodes (P, V, thrust dir U, table index K0, burn left tb) to every
    balloon of the table B (K+1, M, 3) -> (S, M) int, 0 = unreachable. mc > 0: only the mc balloons nearest each node's
    ballistic position 1.5 s ahead are tested. fz: least vertical thrust (GNC never thrusts downward, _saturate);
    hit: miss distance that still pops (inside the balloon radius); Ad: per-node constant drag acceleration."""
    K, M = B.shape[0] - 1, B.shape[1]
    S = len(P)
    if mc and mc < M:
        k15 = np.minimum(K0 + int(round(1.5 / dt)), K)
        d = np.linalg.norm(B[k15] - (P + V * 1.5)[:, None], axis=-1)
        sel = np.argpartition(d, mc - 1, 1)[:, :mc]
    else:
        sel = np.broadcast_to(np.arange(M), (S, M))
    steps = np.r_[np.arange(1, 21), np.arange(22, 61, 2), np.arange(63, T + 1, 3)]  # 0.1 s to 2 s, 0.2 s to 6 s, then 0.3 s
    steps = steps[steps <= T]
    idx = K0[:, None] + steps[None]  # (S, T)
    inside = idx <= K
    tau = (steps * dt).astype(np.float32)[None, :, None, None]
    Bt = B[np.minimum(idx, K)[:, :, None], sel[:, None, :]]  # (S, T, mc, 3), float32 table
    acc = DP_G if Ad is None else (DP_G + Ad)[:, None, None]
    start = (P[:, None, None] + V[:, None, None] * tau + 0.5 * acc * tau ** 2).astype(np.float32)
    miss = Bt - start
    n = np.sqrt(np.einsum("stmk,stmk->stm", miss, miss))
    cos = np.einsum("stmk,sk->stm", miss, U.astype(np.float32)) / np.maximum(n, 1e-6)
    te = np.maximum(tau[..., 0] - td - np.arccos(np.clip(cos, -1.0, 1.0)) / trate, 0.0)  # thrust time after turning
    w = dp_w(te, tb.astype(np.float32)[:, None, None])
    ok = (n <= a * w + hit) & (miss[..., 2] >= fz * w - hit) & inside[:, :, None]
    r = np.where(ok.any(1), steps[np.argmax(ok, 1)], 0)
    out = np.zeros((S, M), int)
    np.put_along_axis(out, np.ascontiguousarray(sel), r, 1)
    return out


def dp_phit(s, tau, post, pc):
    """Prior hit probability of a leg flown at stretch s over tau seconds (half after burnout)."""
    return np.interp(s, (1.05, 1.25, 1.5), pc[:3]) * np.exp(-tau / pc[3]) * np.where(post, 0.5, 1.0)


def dp_legs(B, dt, P, V, K0, tb, U, si, m, k, a, trate, c, elev, Ad):
    """Fly legs (node si -> balloon m in k steps): feasibility incl. the altitude floor along the path and the
    post-burnout cap, arrival velocity and thrust direction (constant-force intercept) -> (ok, V', U', post)."""
    K = B.shape[0] - 1
    k = np.asarray(k, int)
    tau = k * dt
    tbn = tb[si]
    kk = np.minimum(K0[si] + k, K)
    miss = B[kk, m] - P[si] - V[si] * tau[:, None] - 0.5 * (DP_G + Ad[si]) * tau[:, None] ** 2
    nm = np.linalg.norm(miss, axis=1)
    cos = (miss * U[si]).sum(1) / np.maximum(nm, 1e-9)
    te = np.maximum(tau - c["td"] - np.arccos(np.clip(cos, -1.0, 1.0)) / trate, 0.0)
    we = dp_w(te, tbn)
    ok = (k >= 1) & (K0[si] + k <= K) & (nm <= a * we + c["hit"]) & (miss[:, 2] >= c["fz"] * we - c["hit"]) & (tau <= tbn + c["post"])
    wt = np.maximum(dp_w(tau, tbn), 1e-9)
    f = miss / wt[:, None]  # thrust (specific force beyond gravity)
    for q in (0.25, 0.5, 0.75):  # path altitude
        t = q * tau
        z = P[si, 2] + V[si, 2] * t + 0.5 * (Ad[si, 2] - 9.81) * t * t + f[:, 2] * dp_w(t, tbn)
        ok &= z >= elev + c["alt"]
    post = tau > tbn
    Vn = V[si] + (DP_G + Ad[si]) * tau[:, None] + f * np.minimum(tau, tbn)[:, None]
    th = np.where(post[:, None], Vn, f)  # burning: along the thrust; after burnout the nose follows the velocity
    Un = th / np.maximum(np.linalg.norm(th, axis=1, keepdims=True), 1e-9)
    return ok, Vn, Un, post


def dp_plan(B, dt, p, v, u, tb0, a, trate, elev, cfg=None, cur=-1, cur_k=0, force=()):
    """Plan from the rocket state (p, v, body z axis u, burn left tb0) over the balloon table B (K+1, M, 3).
    cur: current target (table index) and cur_k its committed arrival (steps, 0 = none); force: extra root balloons.
    -> dict: root legs (m, k, s, V, com = the committed leg) with the best plan value through each (val),
    the best plan's (m, k) sequence and expected pops (Ep), nodes expanded."""
    c = {**DP_CFG, **(cfg or {})}
    M, B32 = B.shape[1], B.astype(np.float32)
    lam, dmiss, pc = c["lam"], c["dmiss"], c["pc"]
    P, V, U = p[None].astype(float), v[None].astype(float), u[None].astype(float)
    K0, tb, J, Ep = np.zeros(1, int), np.array([float(tb0)]), np.zeros(1), np.zeros(1)  # Ep: expected pops of the legs
    used, first, seq = np.zeros((1, M), bool), np.zeros(1, int), np.zeros((1, 0, 2), int)
    best_val, best_seq, nodes, root = None, None, 0, None

    def drag(P, V):
        """Per-leg constant drag acceleration from each node's air-relative velocity (drag = (k rho, wind grid z, wind W))."""
        if c["drag"] is None:
            return np.zeros_like(V)
        kd, wz, W = c["drag"]
        vr = V - np.stack([np.interp(P[:, 2], wz, W[:, 0]), np.interp(P[:, 2], wz, W[:, 1]), 0.0 * P[:, 2]], 1)
        return -kd * np.linalg.norm(vr, axis=1, keepdims=True) * vr

    def tail(L, tbn):
        """Greedy one-leg tail: the value of the fastest next leg at the smallest stretch; nothing reachable: the burn
        left (up to the leg horizon) is charged at lam; 0 in the coast window."""
        Lf = np.where(L > 0, L, 10 ** 6).min(1) * dt
        s = c["S1"][0]
        tau = np.round(Lf / dt * s) * dt
        ph = dp_phit(s, tau, tau > tbn, pc)
        h = np.where(Lf < 10 ** 5, ph - lam * tau - (1 - ph) * lam * dmiss, -lam * np.minimum(tbn, c["T"] * dt))  # dead end
        return np.where(tbn <= 0, 0.0, h)

    def leaf(mask, L):
        """Leaves (final depth, or no feasible next leg): value = J + tail, best through each root leg."""
        nonlocal best_seq
        if not mask.any():
            return
        val = J[mask] + tail(L[mask], tb[mask])
        np.maximum.at(best_val, first[mask], val)
        i = int(np.argmax(val))
        if best_seq is None or val[i] > best_seq[0]:
            best_seq = (float(val[i]), seq[mask][i], float(Ep[mask][i]))

    for depth in range(c["D"] + 1):
        Ad = drag(P, V)
        L = dp_reach(B32, dt, P, V, K0, tb, U, a, trate, c["td"], c["T"], 0 if depth == 0 else c["mc"], c["fz"], c["hit"], Ad)
        L[used] = 0
        nodes += len(P)
        if depth == c["D"]:
            leaf(np.ones(len(P), bool), L)
            break
        # candidates: the nb fastest balloons of each node (+ forced roots), x stretches
        nb, S = (c["B0"], c["S0"]) if depth == 0 else (c["Bk"], c["S1"])
        Lc = np.where(L > 0, L, 10 ** 6)
        cand = np.argsort(Lc, 1, kind="stable")[:, :nb]
        si, ci = np.nonzero(Lc[np.arange(len(P))[:, None], cand] < 10 ** 6)
        m = cand[si, ci]
        if depth == 0:
            extra = [int(j) for j in set(force) | ({cur} if cur >= 0 else set()) if 0 <= j < M and L[0, j] > 0]
            prot = set(extra)
            m = np.unique(np.r_[m, extra]).astype(int)
            si = np.zeros(len(m), int)
        t1 = L[si, m]
        ns = len(S)
        si, m = np.repeat(si, ns), np.repeat(m, ns)
        s = np.tile(np.asarray(S, float), len(t1))
        k = np.maximum(np.round(np.repeat(t1, ns) * s), 1).astype(int)
        com = np.zeros(len(m), bool)
        if depth == 0 and cur >= 0 and cur_k > 0:  # the committed leg to the current target
            si, m, k = np.r_[si, 0], np.r_[m, cur], np.r_[k, cur_k]
            s = np.r_[s, cur_k / max(L[0, cur], 1)]
            com = np.r_[com, True]
        if not len(m):
            if depth:
                leaf(np.ones(len(P), bool), L)
            break
        ok, Vn, Un, post = dp_legs(B, dt, P, V, K0, tb, U, si, m, k, a, trate, c, elev, Ad)
        if depth:
            has = np.zeros(len(P), bool)
            has[si[ok]] = True
            leaf(~has, L)
        tau = k * dt
        ph = dp_phit(s, tau, post, pc)
        Jn = J[si] + ph - lam * tau - (1 - ph) * lam * dmiss
        Epn = Ep[si] + ph
        Jn = np.where(ok, Jn, -np.inf)
        # dominance merge: same last balloon, |dk| <= dk and |dv| <= dv -> keep the higher J; <= per_m labels a balloon
        cap = len(m) if depth == 0 else c["W"]
        keep, seen = [], {}
        kk_all = K0[si] + k
        for i in np.argsort(-Jn, kind="stable"):
            if not np.isfinite(Jn[i]):
                break
            lst = seen.setdefault(int(m[i]), [])
            if len(lst) >= c["per_m"] or any(abs(kk_all[i] - kk_all[j]) <= c["dk"] and
                                             np.abs(Vn[i] - Vn[j]).max() <= c["dv"] for j in lst):
                if not (depth == 0 and com[i]):  # the committed leg is always kept (compared by the agent)
                    continue
            lst.append(i)
            keep.append(i)
            if len(keep) >= cap:
                break
        if depth and prot:  # the best label through each protected first balloon (current target, forced) survives
            fm = root["m"][first[si]]
            for g in prot - set(fm[keep]):
                ci = np.flatnonzero((fm == g) & np.isfinite(Jn))
                if ci.size:
                    keep.append(int(ci[np.argmax(Jn[ci])]))
        if not keep:
            break
        keep = np.array(keep, int)
        if depth == 0:
            order = np.arange(len(keep))
            root = dict(m=m[keep], k=k[keep], s=s[keep], V=Vn[keep], com=com[keep])
            best_val = np.full(len(keep), -np.inf)
            first = order
        else:
            first = first[si[keep]]
        pk = si[keep]
        seq = np.concatenate([seq[pk], np.stack([m[keep], kk_all[keep]], 1)[:, None]], 1)
        used = used[pk].copy()
        used[np.arange(len(keep)), m[keep]] = True
        P, V, U = B[kk_all[keep], m[keep]].astype(float), Vn[keep], Un[keep]
        tb, K0, J, Ep = np.maximum(tb[pk] - k[keep] * dt, 0.0), kk_all[keep], Jn[keep], Epn[keep]
    if root is None:
        return None
    root["val"] = best_val
    root["seq"] = best_seq[1] if best_seq is not None else np.zeros((0, 2), int)
    root["Ep"] = best_seq[2] if best_seq is not None else 0.0
    root["nodes"] = nodes
    return root

# ============================================================================ RL2 (rl2_agent.py)

import time



N_MAX = 100
STRETCH = (0.6, 0.8, 1.0, 1.3)
DECIDE = 50
F = 15
G_DIM = 62
N_OBS = G_DIM + N_MAX * F
T2_GRID = np.arange(0.25, 15.0, 0.25)


GNC_TUNABLES = ("k_att", "max_rate", "k_rate", "nav_N", "t_go_min", "coast", "min_alt", "lag_comp", "bwind", "margin",
                "eob", "eob_T", "eob_tau", "eob_hold")  # flight tunables a checkpoint may carry (eob*: end-of-burn mode, §135)


def parse_gnc_kw(text):
    """"k_att:3.0+max_rate:2.5" -> {"k_att": 3.0, "max_rate": 2.5} (no "," or "=": safe inside sbatch --export)."""
    out = {}
    for item in filter(None, (text or "").split("+")):
        k, v = item.split(":")
        assert k in GNC_TUNABLES, f"unknown GNC tunable {k!r}"
        out[k] = float(v)
    return out


def reach_time(p, v, bp, bv, a, grid, drift=None):
    """GNC's constant-force reach time, broadcast: p, v (..., 3); bp, bv (..., M, 3) -> (..., M).
    drift (..., M, T, 3): balloon displacement beyond constant velocity at each grid time (GNC bwind)."""
    tg = grid[:, None]
    miss = (bp - p[..., None, :])[..., None, :] + (bv - v[..., None, :])[..., None, :] * tg
    if drift is not None:
        miss = miss + drift
    miss[..., 2] += 4.905 * grid**2
    ok = np.linalg.norm(miss, axis=-1) <= 0.5 * a * grid**2
    return np.where(ok.any(-1), grid[np.argmax(ok, -1)], np.inf)


class RL2Agent(GNCAgent):
    def __init__(self, given_parameters, **kw):
        super().__init__(given_parameters, **kw)
        self.cmd = None
        self.since = 0
        self.n_popped = 0
        self.sl = None  # optional learned reach model: callable(token feats (M,F), stretch) -> (t_hat, p_hat)
        path = Path(kw.get("policy_path", Path(__file__).with_name("rl2_policy.npz")))
        self.net = None
        if kw.get("use_policy", 1) and path.exists():
            self.net = {k: v for k, v in np.load(path).items()}
        self.search_k = int(kw.get("search_k", 0))  # 0 = plain policy argmax; k > 0 = one-step search over top-k
        self.gamma_dec = kw.get("gamma_dec", 0.99)  # PPO discount per decision
        # DP planner (dp_plan.py, dev/plans/dp_planner.md), off by default. dp=1: the planner picks the target after
        # launch; dp=2: it overrides the policy's pick only when its plan is better by dp_delta (dp_delta_sw to leave
        # the current target); dp_shadow=1: the policy acts, the planner only runs. dp_log=1 keeps per-replan records
        self.dp, self.dp_shadow = int(kw.get("dp", 0)), int(kw.get("dp_shadow", 0))
        fl = lambda k, d: tuple(float(x) for x in str(kw.get(k, d)).split("/"))  # noqa: E731  '/'-separated sets
        self.dp_cfg = dict(D=int(kw.get("dp_D", 4)), W=int(kw.get("dp_W", 24)), B0=int(kw.get("dp_B0", 16)),
                           Bk=int(kw.get("dp_Bk", 6)), S0=fl("dp_S", "1.05/1.25/1.5"), S1=fl("dp_S1", "1.05/1.3"),
                           lam=float(kw.get("dp_lam", 0.35)), dmiss=float(kw.get("dp_dmiss", 2.0)),
                           mc=int(kw.get("dp_mc", 40)), td=float(kw.get("dp_td", 0.0)), pc=fl("dp_pc", "0.75/0.9/0.93/20"))
        self.dp_every, self.dp_freeze = int(kw.get("dp_every", 25)), float(kw.get("dp_freeze", 0.5))  # (steps), (s)
        self.dp_switch, self.dp_keep = float(kw.get("dp_switch", 0.2)), float(kw.get("dp_keep", 0.3))
        self.dp_delta, self.dp_delta_sw = float(kw.get("dp_delta", 0.25)), float(kw.get("dp_delta_sw", 0.4))
        self.dp_tarr = str(kw.get("dp_exec", "tarr")) != "stretch"  # fly the planned arrival time (else its stretch)
        self.dp_guard, self.dp_log = float(kw.get("dp_guard", 40.0)), int(kw.get("dp_log", 0))  # (ms) slower: keep cmd
        self.dp_drag = int(kw.get("dp_drag", 0))  # 1: legs include air drag against the history-profile wind
        self.dp_t_arr, self.dp_ovr, self.dp_ms, self.dp_fired, self.dp_rec = np.inf, False, [], 0, []

    # ------------------------------------------------------------------ features
    def needs_decision(self, obs):
        st = obs["balloon_status"][:, 0]
        new = self.cmd is None or int((st == 2).sum()) > self.n_popped or st[self.cmd[0]] != 1
        if self.dp == 1:  # replan every dp_every steps (not in the last dp_freeze s of a leg), at once when passed
            t = float(obs["simulation_time"])
            return new or self._dp_passed(obs, t) or (self.since >= self.dp_every and self.dp_t_arr - t >= self.dp_freeze)
        return new or self.since >= DECIDE or (self.dp_ovr and self._dp_passed(obs, float(obs["simulation_time"])))

    def features(self, obs):
        p, v = self.p_hat, self.v_hat
        st, bs = obs["balloon_status"][:, 0], obs["balloon_states"]
        t = float(obs["simulation_time"])
        a = self.a_thrust - self.margin
        x = np.zeros(N_OBS, np.float32)
        x[:6] = [*(v / 30.0), (p[2] - self.elev) / 100.0, (self.launched_at + self.burn_time - t) / 30.0, self.a_thrust / 15.0]
        alive = np.flatnonzero(st[:N_MAX] == 1)
        if alive.size == 0:
            return x
        bp, bv = bs[alive, :3], bs[alive, 3:]
        rel, relv = bp - p, bv - v
        # radar
        az = ((np.arctan2(rel[:, 1], rel[:, 0]) + np.pi) / (2 * np.pi) * 8).astype(int) % 8
        up = (rel[:, 2] > 0).astype(int)
        rng = np.digitize(np.linalg.norm(rel, axis=1), [40.0, 100.0])
        radar = np.zeros((8, 2, 3))
        np.add.at(radar, (az, up, rng), 1.0)
        x[6:54] = radar.ravel() / 10.0
        x[54:62] = [*(rel.mean(0) / 100.0), *(rel.std(0) / 100.0), up.mean(), alive.size / 100.0]
        # tokens
        if self.bwind >= 2:  # the reach-time feature also follows the balloon-wind profile
            if self.bwind < 4:  # (bwind >= 4 keeps its history profile, updated in get_action)
                self.wprof = self._wind_profile(obs)
            t1 = reach_time(p, v, bp, bv, a, self.t_grid, self._bdrift(bp[:, None, 2], bv[:, None, 2], self.t_grid))
        else:
            t1 = reach_time(p, v, bp, bv, a, self.t_grid)
        t1c = np.where(np.isfinite(t1), t1, 20.0)
        # lookahead: arrive at each balloon (constant-force arrival velocity, as in GNC), then best next reach time
        tc = np.maximum(t1c, 0.5)[:, None]
        arr_p = bp + bv * tc
        arr_v = v + 2 * (bp - p + (bv - v) * tc) / tc
        others = bp[None] + bv[None] * tc[:, :, None]
        t2 = reach_time(arr_p, arr_v, others, np.broadcast_to(bv[None], others.shape), a, T2_GRID)
        t2[np.arange(alive.size), np.arange(alive.size)] = np.inf
        t2 = np.minimum(t2.min(1), 20.0)
        d = np.linalg.norm(bp[:, None] - bp[None], axis=-1)
        cur = self.cmd[0] if self.cmd is not None else -1
        tok = np.zeros((alive.size, F), np.float32)
        tok[:, 0:3] = rel / 50.0
        tok[:, 3:6] = relv / 20.0
        tok[:, 6] = t1c / 10.0
        tok[:, 7] = (bp[:, 2] - self.elev) / 100.0
        tok[:, 8] = alive == cur
        tok[:, 9] = t1c / 10.0  # t_hat: analytic until an SL model is loaded
        tok[:, 10] = np.isfinite(t1)  # p_hat
        tok[:, 11] = t2 / 10.0
        tok[:, 12] = ((d < 30).sum(1) - 1) / 5.0
        tok[:, 13] = ((d < 60).sum(1) - 1) / 10.0
        tok[:, 14] = 1.0
        if self.sl is not None:
            tok[:, 9], tok[:, 10] = self.sl(tok, x[:6])
        x[G_DIM:].reshape(N_MAX, F)[alive] = tok
        return x

    def decide(self, obs, action):
        i, s = int(action[0]), int(action[1])
        st = obs["balloon_status"][:, 0]
        if st[i] != 1:  # masked in the policy; guard anyway
            alive = np.flatnonzero(st == 1)
            i = int(alive[0]) if alive.size else -1
        dp_cmd = len(action) > 2 and isinstance(action[2], tuple)  # DP: (i, s, (i, stretch, t_arr)); a training env's
        self.cmd = None if i < 0 else (action[2] if dp_cmd else (i, STRETCH[s]))  # RL3 action [i, s, launch, u..] is not
        self.since = 0
        self.n_popped = int((st == 2).sum())

    # ------------------------------------------------------------------ numpy network (mirrors dev/rl2_net.py)
    @staticmethod
    def _ln(x, w, b):
        m = x.mean(-1, keepdims=True)
        s = x.var(-1, keepdims=True)
        return (x - m) / np.sqrt(s + 1e-5) * w + b

    def forward(self, x):
        """-> (target logits (N_MAX,), stretch logits (4,), value)."""
        P = self.net
        g = x[:G_DIM]
        tok = x[G_DIM:].reshape(N_MAX, F)
        mask = tok[:, 14] > 0.5
        relu = lambda z: np.maximum(z, 0)
        ge = relu(g @ P["g.w"] + P["g.b"])
        h = self._trunk(tok, ge)
        tl = (h @ P["tgt.w"] + P["tgt.b"])[:, 0] + P["prior"][0] * (-tok[:, 6])
        tl = np.where(mask, tl, -1e9)
        pooled = (h * mask[:, None]).sum(0) / max(mask.sum(), 1)
        pg = np.concatenate([pooled, ge])
        sl = pg @ P["str.w"] + P["str.b"]
        val = (relu(pg @ P["v0.w"] + P["v0.b"]) @ P["v1.w"] + P["v1.b"])[0]
        return tl, sl, val

    def _trunk(self, tok, ge):
        """Token encoder + attention blocks -> (N_MAX, D)."""
        P = self.net
        mask = tok[:, 14] > 0.5
        relu = lambda z: np.maximum(z, 0)
        h = relu(tok @ P["t0.w"] + P["t0.b"]) @ P["t1.w"] + P["t1.b"] + ge
        n_layers = int(P["n_layers"])
        heads = int(P["heads"])
        d = h.shape[-1]
        dh = d // heads
        for L in range(n_layers):
            q = f"l{L}."
            z = self._ln(h, P[q + "ln1.w"], P[q + "ln1.b"])
            qkv = z @ P[q + "in.w"] + P[q + "in.b"]
            Q, Kk, V = np.split(qkv, 3, axis=-1)
            Q = Q.reshape(N_MAX, heads, dh).transpose(1, 0, 2)
            Kk = Kk.reshape(N_MAX, heads, dh).transpose(1, 0, 2)
            V = V.reshape(N_MAX, heads, dh).transpose(1, 0, 2)
            att = Q @ Kk.transpose(0, 2, 1) / np.sqrt(dh)
            att = np.where(mask[None, None, :], att, -1e9)
            att = np.exp(att - att.max(-1, keepdims=True))
            att /= att.sum(-1, keepdims=True)
            o = (att @ V).transpose(1, 0, 2).reshape(N_MAX, d)
            h = h + o @ P[q + "out.w"] + P[q + "out.b"]
            z = self._ln(h, P[q + "ln2.w"], P[q + "ln2.b"])
            h = h + relu(z @ P[q + "ff1.w"] + P[q + "ff1.b"]) @ P[q + "ff2.w"] + P[q + "ff2.b"]
        return h

    # ------------------------------------------------------------------ GNC hooks
    def _select_target(self, p, v, obs):
        if self.cmd is None or obs["balloon_status"][self.cmd[0], 0] != 1:
            return None, None
        if len(self.cmd) > 2 and self.cmd[2] is not None:  # DP leg: arrive at t_arr, aimed on the planner's table
            self.stretch, self.aim_prof = 1.0, self.hprof
            return self.cmd[0], max(self.cmd[2] - float(obs["simulation_time"]), self.t_go_min)
        self.aim_prof = None
        tgt, self.stretch = self.cmd[:2]
        b = obs["balloon_states"][tgt]
        t1 = self._reach_time(p, v, b[None, :3], b[None, 3:])[0]
        return tgt, (t1 if np.isfinite(t1) else self.t_grid[-1])

    def choose(self, obs):
        a = self._dp_choose(obs) if self.dp == 1 else None
        if a is not None:
            return a
        x = self.features(obs)
        tl, sl, _ = self.forward(x)
        s = int(np.argmax(sl))
        a = (int(np.argmax(tl)) if self.search_k <= 0 else self._search(obs, x, tl, s)), s
        return self._dp_choose(obs, tl, a) if self.dp or self.dp_shadow else a

    # ------------------------------------------------------------------ DP planner (dp_plan.py)
    def _dp_passed(self, obs, t):
        """The committed target's closest approach is behind us, after its planned arrival time."""
        b = obs["balloon_states"][self.cmd[0]]
        return t >= self.dp_t_arr and (b[:3] - self.p_hat) @ (b[3:] - self.v_hat) > 0

    def _dp_choose(self, obs, tl=None, a=None):
        """dp=1: plan and pick (None: no plan, the policy decides); dp=2 / dp_shadow: keep or override the policy's
        pick a. -> action (i, s, cmd) with cmd = (i, 1, t_arr) (dp_exec=tarr) or (i, stretch, None)."""
        st, t = obs["balloon_status"][:, 0], float(obs["simulation_time"])
        passed = self.cmd is not None and st[self.cmd[0]] == 1 and self._dp_passed(obs, t)
        cur = self.cmd[0] if self.cmd is not None and st[self.cmd[0]] == 1 and not passed else -1
        self.dp_ovr &= cur >= 0
        t0 = time.perf_counter()
        alive, B = self._btable(obs)
        res, Jm = None, {}
        if alive.size:
            ai = {int(g): j for j, g in enumerate(alive)}
            force = [] if tl is None else [ai[int(g)] for g in np.argsort(-tl)[:3 if self.dp == 2 else 1] if int(g) in ai]
            kc = int(round((self.dp_t_arr - t) / 0.1)) if cur >= 0 and np.isfinite(self.dp_t_arr) else 0
            cfg = dict(self.dp_cfg, B0=8) if self.dp == 2 else dict(self.dp_cfg)  # dp=2 roots: policy top-3 + physics top-8
            if self.dp_drag and self.hprof is not None:
                rho = 1.225 * np.clip(1.0 - 2.2558e-5 * self.p_hat[2], 0.5, 1.0) ** 4.2559
                cfg["drag"] = (self.k_drag * rho, self.hprof[0], self.hprof[1])
            res = dp_plan(B, 0.1, self.p_hat, self.v_hat, quat_to_R(self.q)[:, 2], self.launched_at + self.burn_time - t,
                          self.a_thrust - self.margin, 0.8 * self.max_rate, self.elev, cfg, ai.get(cur, -1), kc, force)
            if res is not None and np.isfinite(res["val"]).any():
                for j in np.argsort(res["val"]):  # best plan value through each first balloon (with a full plan)
                    if np.isfinite(res["val"][j]):
                        Jm[int(alive[res["m"][j]])] = res["val"][j]
            else:
                res = None
        ms = (time.perf_counter() - t0) * 1e3
        slow = ms > self.dp_guard > 0
        self.dp_ms.append(ms)
        self.dp_fired += slow
        g_pi = a[0] if a is not None else -1
        pick = None  # index of the flown root leg
        if res is not None and (not slow or (self.dp == 1 and cur < 0)):  # guard: keep the command / the policy's pick
            val, m = res["val"], res["m"]
            b = int(np.argmax(val))
            gb, Jb = int(alive[m[b]]), val[b]
            if self.dp == 1:
                ic = [j for j in range(len(m)) if alive[m[j]] == cur and np.isfinite(val[j])]
                if ic:  # switch only for dp_switch more; same target: keep the committed arrival if close and feasible
                    jc = max(ic, key=lambda j: val[j])
                    b = b if Jb >= val[jc] + self.dp_switch else jc
                    com = [j for j in ic if res["com"][j]]
                    if alive[m[b]] == cur and com and abs(res["k"][b] - kc) * 0.1 < self.dp_keep:
                        b = com[0]
                pick = b
            elif self.dp == 2:
                if self.dp_ovr:  # an override is held until pop / pass unless the planner clears dp_delta_sw
                    pick = b if gb != cur and Jb - Jm.get(cur, -np.inf) > self.dp_delta_sw else None
                elif gb != g_pi and g_pi in Jm and Jb - Jm[g_pi] > max(self.dp_delta, self.dp_delta_sw * (0 <= cur != gb)):
                    pick = b
        if pick is not None:
            g, k, s = int(alive[res["m"][pick]]), int(res["k"][pick]), float(res["s"][pick])
            self.dp_t_arr, self.dp_ovr = t + k * 0.1, self.dp == 2
            out = (g, 0, (g, 1.0, self.dp_t_arr) if self.dp_tarr else (g, s, None))
        elif cur >= 0 and (self.dp_ovr or (self.dp == 1 and self.cmd is not None)):
            out = (cur, 0, self.cmd)  # hold the override / keep the command (guard)
        else:
            self.dp_t_arr, self.dp_ovr, out = np.inf, False, a
        if self.dp_log:
            self.dp_rec.append(dict(t=t, ms=ms, slow=slow, passed=passed, n_pop=int((st == 2).sum()), pi=g_pi,
                                    tgt=None if out is None else out[0], t_arr=self.dp_t_arr, ovr=self.dp_ovr,
                                    J=None if res is None else float(np.max(res["val"])), Jpi=Jm.get(g_pi), cur=cur, Jcur=Jm.get(cur),
                                    V=None if pick is None else res["V"][pick].copy(), s=None if pick is None else float(res["s"][pick]),
                                    t_end=None if res is None or not len(res["seq"]) else t + (res["seq"][-1][1]) * 0.1,
                                    Ep=None if res is None else res["Ep"], nodes=0 if res is None else res["nodes"]))
        return out

    def _value(self, x):
        return self.forward(x)[2]

    def _search(self, obs, x, tl, s):
        """One-step lookahead: for the policy's top-k targets, predict the hit (prob, time, arrival state),
        rebuild the observation there and score  p_hit * (1 + gamma^n * V(next))."""
        tok = x[-N_MAX * F :].reshape(N_MAX, F)  # tokens are last (RL3 has a longer global part)
        top = [int(i) for i in np.argsort(-tl)[: self.search_k] if tok[i, 14] > 0.5]
        if len(top) <= 1:
            return top[0] if top else int(np.argmax(tl))
        p0, v0, cmd0 = self.p_hat.copy(), self.v_hat.copy(), self.cmd
        t = float(obs["simulation_time"])
        bs, st = obs["balloon_states"], obs["balloon_status"]
        best, best_score = top[0], -np.inf
        for i in top:
            tau = max(float(tok[i, 9]) * 10.0 * (STRETCH[s] if self.sl is None else 1.0), 0.3)
            p_hit = float(tok[i, 10])
            nb = bs.copy()
            nb[:, :3] = bs[:, :3] + bs[:, 3:] * tau
            ns = st.copy()
            ns[i, 0] = 2
            rel = bs[i, :3] - p0 + (bs[i, 3:] - v0) * tau
            self.p_hat, self.v_hat, self.cmd = nb[i, :3].copy(), v0 + 2 * rel / tau, None
            burning = self.launched_at + self.burn_time - (t + tau) > 0
            val = 0.0
            if burning:
                val = self._value(self.features({"simulation_time": t + tau, "balloon_states": nb, "balloon_status": ns}))
            score = p_hit * (1.0 + self.gamma_dec ** (tau / 0.5) * val)
            if score > best_score:
                best, best_score = i, score
        self.p_hat, self.v_hat, self.cmd = p0, v0, cmd0
        return best

    def get_action(self, obs):
        t = float(obs["simulation_time"])
        if self.net is not None and self.p_hat is not None and self._burning(t) and self.needs_decision(obs):
            self.decide(obs, self.choose(obs))
        self.since += 1
        return super().get_action(obs)

# ============================================================================ RL3 (rl3_agent.py)




G3_DIM = G_DIM + 2
N3_OBS = G3_DIM + N_MAX * F
# launch attitude choices (inclination, heading): a checkpoint with an "att" head picks one at launch, else vertical
ATT = [(90.0, 0.0)] + [(i, float(h)) for i in (85.0, 75.0) for h in range(0, 360, 45)]
# 2026-09-25 23:30: steeper tilts (the top teams launch at 62-68 deg and skim the ground first) and "toward the balloons
# still below 10 m" (heading None, computed at launch). Appended, so older 17-way checkpoints keep their meaning.
ATT += [(i, float(h)) for i in (70.0, 65.0, 60.0) for h in range(0, 360, 45)] + [(i, None) for i in (70.0, 65.0, 60.0)]
# continuous launch attitude (a checkpoint with an "attc" head, 2026-09-25 23:45): pre-squash u = (u1, u2) ->
# inclination 55 + 35 sigmoid(u1) deg, heading = toward the balloons near the ground + 180 tanh(u2) deg
ELEV_LO, ELEV_SPAN = 55.0, 35.0


def att_cont(u):
    return ELEV_LO + ELEV_SPAN / (1.0 + np.exp(-float(u[0]))), 180.0 * np.tanh(float(u[1]))
T_MIN, T_MAX = 5.0, 60.0  # T_MIN: default earliest launch decision; a checkpoint may carry its own "t_min"


class RL3Agent(RL2Agent):
    def __init__(self, given_parameters, **kw):
        kw.setdefault("policy_path", "__embedded__")
        super().__init__(given_parameters, **kw)
        if self.net is None and kw.get("use_policy", 1):
            self.net = _embedded_weights()
        if _SL_B64 and kw.get("use_sl", 1):  # learned reach model the policy was trained with
            self.sl = load_sl(io.BytesIO(base64.b64decode(_SL_B64)))
        self.t_min = float(kw.get("t_min", T_MIN))
        if self.net is not None and "t_min" in self.net and "t_min" not in kw:  # the launch floor the policy was
            self.t_min = float(self.net["t_min"])  # trained with; an explicit t_min kwarg wins (e.g. not before 25 s)
        for k, v in (self.net or {}).items():  # GNC tunables the policy was trained with ("gnc.k_att", ...);
            if k.startswith("gnc.") and k[4:] not in kw:  # an explicit kwarg still wins (A/B tests)
                setattr(self, k[4:], float(v))
        self.launch_time = np.inf  # set by the policy (or T_MAX)
        self.pre_since = DECIDE
        # how a deterministic run turns the per-decision launch probabilities into a launch:
        #   "argmax": launch when P(launch) > 0.5 at a decision (training samples, so this can wait far longer)
        #   "median": launch once the chance of having launched by now under the policy, 1 - prod(1 - P), reaches 0.5,
        #             i.e. at the median of the policy's own launch time; still decided online from the observations
        self.launch_rule = kw.get("launch_rule", "argmax")
        self.launch_incl = kw.get("launch_incl", 0.0)  # > 0: override the launch attitude (see decide_launch)
        self.p_wait = 1.0  # prod(1 - P(launch)) over the launch decisions so far

    # ------------------------------------------------------------------ features
    def launched(self):
        return np.isfinite(self.launch_time)

    def needs_launch_decision(self, obs):
        t = float(obs["simulation_time"])
        return not self.launched() and t >= self.t_min and self.pre_since >= DECIDE

    def features(self, obs):
        t = float(obs["simulation_time"])
        pre = self.p_hat is None
        if pre:  # on the pad: fake the post-launch state the RL2 features expect
            saved = (self.p_hat, self.v_hat, self.launched_at)
            self.p_hat, self.v_hat, self.launched_at = np.array([0.0, 0.0, self.elev]), np.zeros(3), t
        x2 = RL2Agent.features(self, obs)
        if pre:
            self.p_hat, self.v_hat, self.launched_at = saved
        x = np.zeros(N3_OBS, np.float32)
        x[: G_DIM] = x2[: G_DIM]
        x[G_DIM : G3_DIM] = [0.0 if pre else 1.0, t / 60.0]
        x[G3_DIM:] = x2[G_DIM :]
        return x

    def _low_heading(self, obs, incl):
        """Launch heading whose tilted body axis points at the airborne balloons below 10 m (their centroid)."""
        bs, st = obs["balloon_states"], obs["balloon_status"][:, 0]
        low = (st == 1) & (bs[:, 2] - self.elev < 10.0)
        if not low.any():
            low = (st == 1) & (bs[:, 2] - self.elev > 0.5)  # none near the ground: the airborne ones
            if not low.any():
                return 0.0
        d = bs[low, :2].mean(0)  # the pad is at the origin
        best, hb = -2.0, 0.0
        for h in range(0, 360, 5):
            z = quat_to_R(np.array(get_initial_attitude(incl, float(h))))[:, 2]
            c = z[:2] @ d / (np.linalg.norm(z[:2]) * np.linalg.norm(d) + 1e-9)
            if c > best:
                best, hb = c, float(h)
        return hb

    def decide_launch(self, obs, launch, att=0):
        t = float(obs["simulation_time"])
        self.att_last = att  # a launch forced at T_MAX between decisions uses the last choice
        if launch or t >= T_MAX:
            self.launch_time = t
            if np.ndim(att) == 1:  # continuous head: (u1, u2)
                incl, off = att_cont(att)
                head = (self._low_heading(obs, incl) + off) % 360.0
            else:
                incl, head = ATT[att]
            if self.launch_incl:  # experiment override (2026-09-25 23:20): this tilt, toward the balloons near the ground
                incl, head = self.launch_incl, None
            self.incl_head = np.array([incl, self._low_heading(obs, incl) if head is None else head])
            self.q = np.array(get_initial_attitude(*self.incl_head))
        self.pre_since = 0

    # ------------------------------------------------------------------ numpy network (mirrors dev/rl3_net.py)
    def forward(self, x):
        """-> (target logits, stretch logits, launch logits (2,), value, attitude logits (len(ATT),) or attitude mean u (2,))."""
        P = self.net
        g, tok = x[:G3_DIM], x[G3_DIM:].reshape(N_MAX, F)
        relu = lambda z: np.maximum(z, 0)
        ge = relu(g @ P["g.w"] + P["g.b"])
        h = RL2Agent._trunk(self, tok, ge)
        mask = tok[:, 14] > 0.5
        tl = (h @ P["tgt.w"] + P["tgt.b"])[:, 0] + P["prior"][0] * (-tok[:, 6])
        tl = np.where(mask, tl, -1e9)
        pooled = (h * mask[:, None]).sum(0) / max(mask.sum(), 1)
        pg = np.concatenate([pooled, ge])
        sl = pg @ P["str.w"] + P["str.b"]
        ll = pg @ P["lau.w"] + P["lau.b"]
        ll = ll + np.array([0.0, P["lprior"][0] * (x[G_DIM + 1] * 60.0 - 20.0)])
        val = (relu(pg @ P["v0.w"] + P["v0.b"]) @ P["v1.w"] + P["v1.b"])[0]
        if "attc.w" in P:  # continuous attitude: the mean of u (2,)
            al = pg @ P["attc.w"] + P["attc.b"]
        else:
            al = pg @ P["att.w"] + P["att.b"] if "att.w" in P else np.eye(len(ATT))[0]  # no head: vertical
        return tl, sl, ll, val, al

    def _value(self, x):
        return self.forward(x)[3]

    def choose(self, obs):
        a = self._dp_choose(obs) if self.dp == 1 else None  # DP planner (RL2Agent._dp_choose)
        if a is not None:
            return a
        x = self.features(obs)
        tl, sl, *_ = self.forward(x)
        s = int(np.argmax(sl))
        a = (self._search(obs, x, tl, s) if self.search_k > 0 else int(np.argmax(tl))), s
        return self._dp_choose(obs, tl, a) if self.dp or self.dp_shadow else a

    def get_action(self, obs):
        t = float(obs["simulation_time"])
        if self.net is not None and self.needs_launch_decision(obs):
            _, _, ll, _, al = self.forward(self.features(obs))
            if self.launch_rule == "median":
                e = np.exp(ll - ll.max()); self.p_wait *= 1.0 - e[1] / e.sum()
                go = self.p_wait <= 0.5
            else:
                go = int(np.argmax(ll)) == 1
            self.decide_launch(obs, go, al if "attc.w" in self.net else int(np.argmax(al)))
        elif not self.launched() and t >= T_MAX:
            self.decide_launch(obs, True, getattr(self, "att_last", 0))
        self.pre_since += 1
        if self.net is not None and self.p_hat is not None and self._burning(t) and self.needs_decision(obs):
            self.decide(obs, self.choose(obs))
        self.since += 1
        return super(RL2Agent, self).get_action(obs)  # GNC: launches when t >= launch_time
